test('lateFee with combination of VAT, discount, and payment', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    dueDate: '2026-10-15',
    status: 'partially_paid',
    number: 'INV-2026-0001',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 10000, vatRate: 21, discountPercent: 10 }],
    payments: [{ amount: 3000, date: '2026-10-20' }],
  };

  const result = lateFee(invoice, '2026-10-31');
  // Base = 10000 - 1000 = 9000
  // VAT = 9000 * 21 / 100 = 1890
  // Total = 9000 + 1890 = 10890
  // Due = 10890 - 3000 = 7890
  // 16 days overdue
  // Fee = 7890 * 16 * 0.04 / 100 = 5049.6 → 5050 cents (banker's rounding)
  assert.equal(result, 5050);
});

