  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    dueDate: '2026-10-15',
    status: 'issued',
    number: 'INV-2026-0001',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 200, vatRate: 0, discountPercent: 0 }],
  };

  const result = lateFee(invoice, '2026-10-31');
  // 16 days overdue, Total = 200
  // Fee = 200 * 16 * 0.04 / 100 = 12.8 → 13 cents (banker's rounding, 12.8 rounds to 13)
  assert.equal(result, 13);
});

